inputs.script:
$ErrorActionPreference = 'Stop'

# --- environment sanity -------------------------------------------------
$required = @('BUILD_SOURCEBRANCHNAME','BUILD_BUILDID','SETTLEMENT_ENV')
foreach ($name in $required) {
  $value = [Environment]::GetEnvironmentVariable($name)
  if ([string]::IsNullOrWhiteSpace($value)) {
    Write-Host "##vso[task.logissue type=error]missing required variable $name"
    exit 1
  }
  Write-Host "checked $name"
}

# --- derive the release version ----------------------------------------
$branch = $env:BUILD_SOURCEBRANCHNAME
$buildId = $env:BUILD_BUILDID
$major = 4
$minor = 2
switch -Wildcard ($branch) {
  'main'      { $suffix = ''; break }
  'release*'  { $suffix = '-rc'; break }
  'hotfix*'   { $suffix = '-hf'; break }
  default     { $suffix = '-dev'; break }
}
$version = "$major.$minor.$buildId$suffix"
Write-Host "resolved version $version for branch $branch"
Write-Host "##vso[task.setvariable variable=settlementVersion]$version"

# --- write the legacy build manifest the downstream release job reads ---
$stagingDir = $env:BUILD_ARTIFACTSTAGINGDIRECTORY
New-Item -ItemType Directory -Force -Path $stagingDir | Out-Null
$manifestPath = Join-Path $stagingDir 'build-manifest.json'
$manifest = [ordered]@{
  component   = 'settlement-gateway'
  version     = $version
  branch      = $branch
  buildId     = $buildId
  environment = $env:SETTLEMENT_ENV
  builtAtUtc  = (Get-Date).ToUniversalTime().ToString('o')
  checksums   = @{}
}

# --- checksum every source file so the manifest is reproducible ---------
$sourceRoot = Join-Path $env:BUILD_SOURCESDIRECTORY 'services/settlement-gateway/src'
if (-not (Test-Path $sourceRoot)) {
  Write-Host "##vso[task.logissue type=error]source root $sourceRoot does not exist"
  exit 1
}
Get-ChildItem -Path $sourceRoot -Recurse -Filter '*.py' | ForEach-Object {
  $relative = $_.FullName.Substring($env:BUILD_SOURCESDIRECTORY.Length + 1)
  $hash = (Get-FileHash -Path $_.FullName -Algorithm SHA256).Hash
  $manifest.checksums[$relative] = $hash
  Write-Host "hashed $relative"
}

$manifest | ConvertTo-Json -Depth 5 | Set-Content -Path $manifestPath -Encoding utf8
Write-Host "wrote $manifestPath"
